def copiar_status(apps, schema_editor):
    """«Entidade ativa» (sim/não) passa a «Status» (lista configurável)."""
    Lista = apps.get_model("configuracao", "Lista")
    Valor = apps.get_model("configuracao", "ValorLista")
    Entidade = apps.get_model("entidades", "Entidade")
    lista, _ = Lista.objects.get_or_create(
        chave="status_entidade",
        defaults={
            "nome": "Status da entidade",
            "modulo": "entidades",
            "categorias": [
                {"valor": "ativo", "nome": "Ativo"},
                {"valor": "inativo", "nome": "Inativo"},
                {"valor": "arquivado", "nome": "Arquivado (escondido por omissão)"},
            ],
        },
    )
    ativo, _ = Valor.objects.get_or_create(lista=lista, nome="Ativo", defaults={"categoria": "ativo", "ordem": 0})
    inativo, _ = Valor.objects.get_or_create(
        lista=lista, nome="Inativo", defaults={"categoria": "inativo", "ordem": 1}
    )
    Entidade.objects.filter(ativa=True).update(status=ativo)
    Entidade.objects.filter(ativa=False).update(status=inativo)
    Lista.objects.filter(chave="papeis_entidade", nome="Papéis de entidade").update(
        nome="Tipos de cliente", descricao="Proprietário, comprador, arrendatário…"
    )


